function capOutline({notch=false,scallops=false}={}){const s=new THREE.Shape();s.moveTo(-8,-23);if(notch){s.lineTo(-5.2,-23);s.lineTo(-5.2,-17.1);s.lineTo(5.2,-17.1);s.lineTo(5.2,-23);}s.lineTo(8,-23);s.absarc(8,-20,3,-Math.PI/2,0,false);if(scallops){s.lineTo(11,-15.2);s.lineTo(8,-15.2);s.absarc(8,-12,3.2,-Math.PI/2,-Math.PI*1.5,true);s.lineTo(11,-8.8);}s.lineTo(11,20);s.absarc(8,20,3,0,Math.PI/2,false);s.lineTo(-8,23);s.absarc(-8,20,3,Math.PI/2,Math.PI,false);if(scallops){s.lineTo(-11,-8.8);s.lineTo(-8,-8.8);s.absarc(-8,-12,3.2,Math.PI/2,-Math.PI/2,true);s.lineTo(-11,-15.2);}s.lineTo(-11,-20);s.absarc(-8,-20,3,Math.PI,Math.PI*1.5,false);s.closePath();return s;}
function sideProfile(sign,start=0){const s=new THREE.Shape();s.moveTo(-start,24);s.lineTo(-8,24);s.absarc(-8,20,4,Math.PI/2,Math.PI,false);s.lineTo(-12,-20);s.absarc(-8,-20,4,Math.PI,Math.PI*1.5,false);s.lineTo(-5.2,-24);s.lineTo(-5.2,-23);s.lineTo(-8,-23);s.absarc(-8,-20,3,Math.PI*1.5,Math.PI,true);s.lineTo(-11,20);s.absarc(-8,20,3,Math.PI,Math.PI/2,true);s.lineTo(-start,23);s.closePath();return sign<0?s:polygon(s.getPoints(40).map(v=>[-v.x,v.y]).reverse());}
function shell(host){const white=plastic(0xe8e7df),frontShape=capOutline({notch:true});for(const x of[-8,8])hole(frontShape,x,-12,2.5);const front=solid(host.body,frontShape,1,[0,0,2.9],white,'GPS U032 own complete front pan and two drawing Ø5 bores'),frontRimShape=capOutline({notch:true,scallops:true});frontRimShape.holes.push(roundedRect(18.3,28.3,.2,{cy:7.3,path:new THREE.Path()}));const frontRim=solid(host.body,frontRimShape,.1,[0,0,3.9],white,'GPS U032 own front film recess and scalloped mounting band');
 const backShape=capOutline();for(const x of[-8,8])hole(backShape,x,-12,2.5);hole(backShape,0,-12,1.65);const back=solid(host.body,backShape,1,[0,0,-3.9],white,'GPS U032 own complete rear pan and physical mounting/fixing bores'),rearShape=capOutline({scallops:true});hole(rearShape,0,-12,1.65);rearShape.holes.push(roundedRect(16.3,28.3,.2,{cy:7,path:new THREE.Path()}));const m=polygon([[-4.6,-21.7],[-4.6,-16.3],[-3.85,-16.3],[-2.25,-18.5],[-.65,-16.3],[.1,-16.3],[.1,-21.7],[-.65,-21.7],[-.65,-17.6],[-2.25,-19.8],[-3.85,-17.6],[-3.85,-21.7]]),five=polygon([[.6,-16.23],[4.5,-16.23],[4.5,-16.98],[1.35,-16.98],[1.35,-18.3],[3.3,-18.3],[4.1,-18.75],[4.55,-19.8],[4.3,-20.95],[3.45,-21.63],[.6,-21.63],[.6,-20.88],[3.15,-20.88],[3.8,-20.43],[3.8,-19.48],[3.2,-19.05],[.6,-19.05]]);rearShape.holes.push(m,five);const rearRim=solid(host.body,rearShape,.1,[0,0,-4],white,'GPS U032 actual uncolored rear M5 recess and label seat rim'),frontEdge=rolledEdge(host.body,{front:true,material:white}),rearEdge=rolledEdge(host.body,{front:false,material:white});
 const left=solid(host.body,sideProfile(-1),6,[0,0,-3],white,'GPS own continuous R4 left case wall'),rightBottom=solid(host.body,sideProfile(1),2.2,[0,0,-3],white,'GPS own R4 right wall below passive top notch'),rightTop=solid(host.body,sideProfile(1),2.1,[0,0,.9],white,'GPS own R4 right wall above passive top notch'),rightMiddle=solid(host.body,sideProfile(1,7.8),1.7,[0,0,-.8],white,'GPS own right midwall with actual top notch cut'),topBridge=box(host.body,[6.2,1,1.7],[3.1,23.5,.05],white,'GPS actual top closure beside passive notch'),notchWalls=[6.05,7.95].map(x=>box(host.body,[.3,2,1.7],[x,23,.05],white,'GPS actual passive top-notch side wall')),notchStop=box(host.body,[2.2,.4,1.7],[7,21.8,.05],white,'GPS actual deep blind support behind unconfirmed top notch'),bottom=box(host.body,[10.4,1,1.7],[0,-23.5,-2.15],white,'GPS actual closed bottom rear wall beneath blue socket');
 const bores=[-8,8].map(x=>ring(host.body,3,2.5,5.8,[x,-12,-2.9],white,'GPS actual drawing Ø5 through mounting tube')),rearBoss=ring(host.body,2.6,1.65,2.2,[0,-12,-2.9],white,'GPS actual central rear screw pedestal'),frontBoss=ring(host.body,2.6,.75,3.6,[0,-12,-.7],white,'GPS actual retained front screw receiver through PCB clearance'),frontFilm=solid(host.body,roundedRect(18,28,.12),.04,[0,7.3,3.9],plastic(0xe6e3d8),'GPS actual front location-mark adhesive film'),backFilm=solid(host.body,roundedRect(16,28,.12),.04,[0,7,-3.94],plastic(0xe6e3d8),'GPS actual rear identification adhesive film');for(const f of[frontFilm,backFilm])f.userData={role:'physical-label-substrate',thicknessInferred:true};return{front,frontRim,back,rearRim,frontEdge,rearEdge,left,rightBottom,rightTop,rightMiddle,topBridge,notchWalls,notchStop,bottom,bores,rearBoss,frontBoss,frontFilm,backFilm};}
function pcbOutline(){const s=new THREE.Shape(),r=3.35,dx=10.2-8,q=Math.acos(dx/r),dy=Math.sqrt(r*r-dx*dx);s.moveTo(-8.2,-22);s.lineTo(8.2,-22);s.lineTo(10.2,-20);s.lineTo(10.2,-12-dy);s.absarc(8,-12,r,-q,q,true);s.lineTo(10.2,20);s.lineTo(8.2,22);s.lineTo(-8.2,22);s.lineTo(-10.2,20);s.lineTo(-10.2,-12+dy);s.absarc(-8,-12,r,Math.PI-q,Math.PI+q,true);s.lineTo(-10.2,-20);s.closePath();hole(s,0,-12,3.1);for(const x of[-3,-1,1,3])hole(s,x,-18.4,.38);return s;}
function board(host){const pcb=solid(host.body,pcbOutline(),.8,[0,0,-2],plastic(0x2b694b),'GPS own inferred retained PCB with true open-edge bore reliefs'),posts=[];for(const x of[-8.8,8.8])for(const y of[-19.7,19.5])posts.push(box(host.body,[1,1,.9],[x,y,-2.45],plastic(0xd9d9cd),'GPS actual reconstructed PCB post from rear pan'));
 const passives=[],terminations=[];for(const[x,y]of[[-7.8,-.8],[-7.8,2.3],[7.8,6],[7.8,9],[-6.2,-5.3],[-2.8,-5.3],[1.4,-5.3],[5.2,-5.3]]){passives.push(box(host.body,[1.45,.75,.45],[x,y,-.975],plastic(0x8b8a77),'GPS inferred supporting fixed passive envelope,not full BOM'));for(const sign of[-1,1])terminations.push(box(host.body,[.3,.8,.46],[x+sign*.61,y,-.97],tin(),'GPS retained supporting passive termination'));}return{pcb,posts,passives,terminations};}
function receiver(host){const centre=[-2.6,-.6],body=box(host.body,[5,5,.85],[...centre,-.695],plastic(0x242922),'GPS documented AT6558 fixed envelope;package/position inferred'),lands=[],contacts=[];for(const sign of[-1,1])for(let i=0;i<6;i++){const d=(i-2.5)*.7;for(const[x,y,wx,wy]of[[centre[0]+sign*2.4,centre[1]+d,.5,.35],[centre[0]+d,centre[1]+sign*2.4,.35,.5]]){contacts.push(box(host.body,[wx,wy,.08],[x,y,-1.16],tin(),'GPS inferred AT6558 retained contact'));lands.push(box(host.body,[wx+.12,wy+.12,.025],[x,y,-1.1875],tin(),'GPS inferred actual receiver solderland'));}}const amp=box(host.body,[1.5,1.5,.5],[5.6,1.8,-.87],plastic(0x242922),'GPS documented MAX2659 fixed envelope;package/position inferred'),ampContacts=[],ampLands=[];for(const sign of[-1,1])for(let i=0;i<3;i++){const x=5.6+sign*.72,y=1.8+(i-1)*.48;ampContacts.push(box(host.body,[.4,.24,.08],[x,y,-1.16],tin(),'GPS inferred MAX2659 retained contact'));ampLands.push(box(host.body,[.52,.36,.025],[x,y,-1.1875],tin(),'GPS inferred amplifier supporting solderland'));}return{body,lands,contacts,amp,ampContacts,ampLands,scope:'AT6558/MAX2659 documentary identities only;hidden package shape/count/coordinates inferred,not exact BOM'};}
function antenna(host){const feet=[-4.8,4.8].map(x=>box(host.body,[1.2,10.5,.3],[x,9,-1.05],tin(),'GPS inferred retained passive antenna support')),substrate=box(host.body,[13,13,1.3],[0,9,-.25],plastic(0xd2c9ad),'GPS inferred fixed ceramic antenna envelope;actual package unconfirmed'),metallization=box(host.body,[10.8,10.8,.035],[0,9,.4175],materials.metal(0xb8aa78,{roughness:.58}),'GPS inferred fixed antenna metal surface;no RF behavior');return{feet,substrate,metallization,scope:'Generic fixed appearance support only;no precise native antenna assembly was established by exterior source'};}
function grove(host){const frame=new THREE.Group();frame.name='GPS original U032 actual blue Grove receiver';frame.position.fromArray(spec.grove.position);frame.quaternion.copy(FACE.bottom);host.body.add(frame);const blue=plastic(0x099ace),parts=[],b=(s,p,n,m=blue)=>{const o=box(frame,s,p,m,'GPS Grove '+n);parts.push(o);return o;},floor=b([10,.65,6.2],[0,-2.275,-3.1],'real PCB-side molded floor'),back=b([10,4.55,.5],[0,-.325,-5.95],'actual deep receiving stop'),walls=[-1,1].map(sign=>b([.7,5.2,6.2],[sign*4.65,0,-3.1],'actual receiving side wall')),bridge=b([4.8,.45,2.8],[0,1.7,-3.6],'actual partial retention bridge'),guides=[-1,1].map(sign=>b([.7,.5,2.8],[sign*4,-1.7,-1.4],'actual mating guide')),contacts=[],returns=[],tails=[],barrels=[],pads=[];
 for(const x of[-3,-1,1,3]){contacts.push(b([.32,.32,4.8],[x,-.2,-3.1],'independent retained contact',tin()));returns.push(b([.32,2.4,.32],[x,-1.4,-5.6],'actual right-angle return',tin()));tails.push(box(host.body,[.32,.32,.8],[x,-18.4,-1.6],tin(),'GPS actual through-PCB retained conductor tail'));barrels.push(ring(host.body,.36,.26,.8,[x,-18.4,-2],tin(),'GPS actual plated receiving barrel'));for(const z of[-2.025,-1.2])pads.push(ring(host.body,.65,.26,.025,[x,-18.4,z],tin(),'GPS actual annular solderland'));}
 const port=host.add(new Port({id:'grove',label:'Original U032 blue HY2.0 four-contact receiving socket',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('bottom'),hitSize:[10,1,5.2],pinGrid:{cols:4,rows:1,pitch:2,center:[0,-.2],order:i=>4-i},pins:spec.grove.pins.map((name,i)=>({n:i+1,name})),meta:{role:'visual-connector',face:'bottom',scope:'Mechanical four-contact connector only;no positioning/NMEA/fix/satellite/UTC/UART/electrical/firmware behavior'}}));return{frame,parts,floor,back,walls,bridge,guides,contacts,returns,tails,barrels,pads,port};}
function fixing(host){const shape=new THREE.Shape();shape.absarc(0,0,1.5,0,Math.PI*2,false);const hex=[];for(let i=0;i<6;i++)hex.push([.72*Math.cos(i/6*Math.PI*2),.72*Math.sin(i/6*Math.PI*2)]);shape.holes.push(polygon(hex));const head=solid(host.body,shape,.45,[0,-12,-3.88],tin(),'GPS actual rear retained hex-socket screw head'),floor=cylinder(host.body,.9,.1,[0,-12,-3.38],plastic(0x292b26),'GPS actual blind screw socket floor'),shank=cylinder(host.body,.65,4.7,[0,-12,-1.03],tin(),'GPS actual fixed central screw shank retained in front boss');return{head,floor,shank};}
export function buildGPS(host){const shellParts=shell(host),boardParts=board(host),rx=receiver(host),ant=antenna(host),input=grove(host),screw=fixing(host);host.gpsAssembly={frame:shellParts.front.parent,shell:shellParts,board:boardParts,receiver:rx,antenna:ant,input,screw};host.unitStickers=addStickers(host);}
